public final class HammerAudit {
 public static void prepare(ServerLevel l,BlockPos base){for(int x=6;x<=10;x++)for(int z=6;z<=10;z++)l.setChunkForced((base.getX()>>4)+x,(base.getZ()>>4)+z,true);}
 private static EntityArcher sentry;private static Zombie enemy;private static boolean targeted,shot;private static ChunkPos forced;
 private static void check(String n,boolean ok,Object info){ServerAudit.check("hammer: "+n,ok,info);}
 private static ItemStack item(String id){return EMTRecipes.stack(id);}
 private static ItemStack charged(double eu){var s=item("emt:electric_mjolnir");ElectricItem.manager.charge(s,eu,10,true,false);return s;}
 private static void attack(ServerPlayer p,ItemStack stack,Pig pig){p.setItemInHand(InteractionHand.MAIN_HAND,stack);stack.forEachModifier(EquipmentSlot.MAINHAND,(attribute,modifier)->{var instance=p.getAttribute(attribute);if(instance!=null){instance.removeModifier(modifier.id());instance.addTransientModifier(modifier);}});p.setOnGround(true);p.setDeltaMovement(Vec3.ZERO);p.fallDistance=0;p.setSprinting(false);try{var f=LivingEntity.class.getDeclaredField("attackStrengthTicker");f.setAccessible(true);f.setInt(p,100);}catch(Exception ex){throw new RuntimeException(ex);}pig.setHealth(20);pig.invulnerableTime=0;p.attack(pig);}
 public static void run(ServerLevel l,BlockPos base){var p=new ServerPlayer(l.getServer(),l,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"EMTHammerAudit"),ClientInformation.createDefault());p.connection=FakePlayerFactory.getMinecraft(l).connection;p.setGameMode(GameType.SURVIVAL);p.getAbilities().invulnerable=false;p.setPos(base.getX()+120.5,base.getY()+3,base.getZ()+100.5);p.setYRot(0);p.setXRot(0);
  var normal=item("emt:mjolnir");var broken=item("emt:tainted_mjolnir");var electric=charged(10000);check("original custom sword durability2000/1000/27",normal.getMaxDamage()==2000&&broken.getMaxDamage()==1000&&electric.getMaxDamage()==27,normal.getMaxDamage()+"/"+broken.getMaxDamage()+"/"+electric.getMaxDamage());var e=(ItemElectricThorHammer)electric.getItem();check("original electric profile1MEU/tier2/transfer100",e.getMaxCharge(electric)==1000000&&e.getTier(electric)==2&&e.getTransferLimit(electric)==100,"profile");
  var pig=new Pig(EntityType.PIG,l);pig.getAttribute(Attributes.MAX_HEALTH).setBaseValue(20);pig.setPos(p.position().add(0,0,2));attack(p,normal,pig);check("native player attack applies12total hammer damage",Math.abs(pig.getHealth()-8)<.001,pig.getHealth());check("native hammer melee costs one durability",normal.getDamageValue()==1,normal.getDamageValue());attack(p,broken,pig);check("broken hammer keeps original diamond hit and lower followup semantics",Math.abs(pig.getHealth()-13)<.001,pig.getHealth());attack(p,electric,pig);check("native electric attack applies19total for5000EU",Math.abs(pig.getHealth()-1)<.001&&ElectricItem.manager.getCharge(electric)==5000,pig.getHealth()+"/"+ElectricItem.manager.getCharge(electric));check("electric melee never consumes sword durability",electric.getDamageValue()==0,electric.getDamageValue());var empty=charged(4999);attack(p,empty,pig);check("empty hammer retains diamond hit without partial EU debit",Math.abs(pig.getHealth()-13)<.001&&ElectricItem.manager.getCharge(empty)==4999,pig.getHealth()+"/"+ElectricItem.manager.getCharge(empty));
  var target=p.blockPosition().offset(0,1,6);l.setBlock(target,Blocks.STONE.defaultBlockState(),3);p.setItemInHand(InteractionHand.MAIN_HAND,normal);int oldDamage=normal.getDamageValue();normal.use(l,p,InteractionHand.MAIN_HAND);var bolts=l.getEntitiesOfClass(LightningBolt.class,p.getBoundingBox().inflate(12));check("normal hammer ray creates one actual aimed lightning and costs20durability",bolts.size()==1&&normal.getDamageValue()==oldDamage+20,bolts.size());bolts.forEach(Entity::discard);p.setXRot(-90);oldDamage=normal.getDamageValue();normal.use(l,p,InteractionHand.MAIN_HAND);check("missed lightning trace does not damage hammer",normal.getDamageValue()==oldDamage,"miss");p.setXRot(0);
  p.setItemInHand(InteractionHand.MAIN_HAND,broken);oldDamage=broken.getDamageValue();broken.use(l,p,InteractionHand.MAIN_HAND);var orbs=l.getEntitiesOfClass(thaumcraft.common.entities.projectile.EntityAlumentum.class,p.getBoundingBox().inflate(11));check("broken relic creates six real native alumentum projectiles for20durability",orbs.size()==6&&broken.getDamageValue()==oldDamage+20,orbs.size());orbs.forEach(Entity::discard);
  var storm=charged(100000);p.setItemInHand(InteractionHand.MAIN_HAND,storm);storm.use(l,p,InteractionHand.MAIN_HAND);bolts=l.getEntitiesOfClass(LightningBolt.class,p.getBoundingBox().inflate(12));var archers=l.getEntitiesOfClass(EntityArcher.class,p.getBoundingBox().inflate(12));check("supercharged storm creates24actual lightning and four guardians",bolts.size()==24&&archers.size()==4,bolts.size()+"/"+archers.size());check("storm debits exactly75000EU and guardians have40health",ElectricItem.manager.getCharge(storm)==25000&&archers.stream().allMatch(a->a.getMaxHealth()==40&&a.getHealth()==40),ElectricItem.manager.getCharge(storm));check("all24storm offsets are distinct",ItemElectricThorHammer.stormOffsets().stream().distinct().count()==24,"offsets");bolts.forEach(Entity::discard);archers.forEach(Entity::discard);
  var failed=charged(74999);p.setItemInHand(InteractionHand.MAIN_HAND,failed);failed.use(l,p,InteractionHand.MAIN_HAND);bolts=l.getEntitiesOfClass(LightningBolt.class,p.getBoundingBox().inflate(2));check("insufficient storm strikes caster and applies original harm1 without partial debit",bolts.size()==1&&p.hasEffect(net.minecraft.world.effect.MobEffects.HARM)&&p.getEffect(net.minecraft.world.effect.MobEffects.HARM).getAmplifier()==1&&ElectricItem.manager.getCharge(failed)==74999,bolts.size());bolts.forEach(Entity::discard);p.removeAllEffects();p.setGameMode(GameType.CREATIVE);storm.use(l,p,InteractionHand.MAIN_HAND);check("reference creative electric rightclick does nothing",l.getEntitiesOfClass(LightningBolt.class,p.getBoundingBox().inflate(12)).isEmpty()&&ElectricItem.manager.getCharge(storm)==25000,"creative");
  p.setGameMode(GameType.SURVIVAL);p.setXRot(0);var summoner=item("emt:lightning_summoner").copyWithCount(2);p.setItemInHand(InteractionHand.MAIN_HAND,summoner);summoner.use(l,p,InteractionHand.MAIN_HAND);summoner.getItem().onUseTick(l,p,summoner,72000-39);check("summoner waits original40ticks without consuming item",summoner.getCount()==2&&p.isUsingItem()&&l.getEntitiesOfClass(LightningBolt.class,p.getBoundingBox().inflate(12)).isEmpty(),"39ticks");summoner.getItem().onUseTick(l,p,summoner,72000-40);bolts=l.getEntitiesOfClass(LightningBolt.class,p.getBoundingBox().inflate(12));check("summoner uses same loaded ray and consumes exactly one at40ticks",bolts.size()==1&&summoner.getCount()==1&&!p.isUsingItem(),"40ticks");bolts.forEach(Entity::discard);p.setXRot(-90);summoner.use(l,p,InteractionHand.MAIN_HAND);summoner.getItem().onUseTick(l,p,summoner,72000-40);check("missed summoner ray consumes nothing and stops use",summoner.getCount()==1&&!p.isUsingItem(),"miss");p.setXRot(0);p.setGameMode(GameType.CREATIVE);summoner.use(l,p,InteractionHand.MAIN_HAND);summoner.getItem().onUseTick(l,p,summoner,72000-40);bolts=l.getEntitiesOfClass(LightningBolt.class,p.getBoundingBox().inflate(12));check("creative summoner strikes without consumption",bolts.size()==1&&summoner.getCount()==1,"creative");bolts.forEach(Entity::discard);
  var pos=base.offset(128,1,128);forced=new ChunkPos(pos);l.setChunkForced(forced.x,forced.z,true);for(var floor:BlockPos.betweenClosed(pos.offset(-6,-1,-6),pos.offset(6,-1,12)))l.setBlock(floor,Blocks.STONE.defaultBlockState(),3);sentry=new EntityArcher(EMTEntities.ARCHER.get(),l);sentry.setPos(Vec3.atBottomCenterOf(pos));l.addFreshEntity(sentry);enemy=new Zombie(l);enemy.setPos(sentry.position().add(0,0,5));l.addFreshEntity(enemy);sentry.performRangedAttack(enemy,1);var arrows=l.getEntitiesOfClass(Arrow.class,sentry.getBoundingBox().inflate(2));check("guardian shoots real arrows rather than snowballs",arrows.size()==1&&arrows.getFirst().getOwner()==sentry,arrows.size());arrows.forEach(Entity::discard);check("guardian uses original40health/.3speed and snow-golem body",sentry instanceof net.minecraft.world.entity.animal.SnowGolem&&sentry.getMaxHealth()==40&&sentry.getAttributeValue(Attributes.MOVEMENT_SPEED)==.3,"attributes");
  var doomed=new EntityArcher(EMTEntities.ARCHER.get(),l);var deathPos=base.offset(150,2,100);doomed.setPos(Vec3.atCenterOf(deathPos));l.setBlock(deathPos,Blocks.GLASS.defaultBlockState(),3);l.addFreshEntity(doomed);doomed.setHealth(0);doomed.die(doomed.damageSources().generic());check("guardian death triggers a real block explosion and removes entity",doomed.isRemoved()&&l.isEmptyBlock(deathPos),"explosion");
  var lootKey=ResourceKey.create(Registries.LOOT_TABLE,ResourceLocation.withDefaultNamespace("chests/simple_dungeon"));var table=l.getServer().reloadableRegistries().getLootTable(lootKey);var params=new LootParams.Builder(l).withParameter(LootContextParams.ORIGIN,p.position()).create(LootContextParamSets.CHEST);boolean found=false;for(int i=0;i<150;i++)for(var result:table.getRandomItems(params,(long)i))if(result.is(EMTItems.HAMMERS.get("tainted_mjolnir").get()))found=true;check("actual weighted dungeon rolls produce broken relic",found,"150 rolls");check("legend,OneRing andLightningSummoner original auto researches exist",thaumcraft.api.research.ResearchCategories.getResearch("The Legend").isAutoUnlock()&&thaumcraft.api.research.ResearchCategories.getResearch("The One Ring").isAutoUnlock()&&thaumcraft.api.research.ResearchCategories.getResearch("Lightning Summoner").isAutoUnlock(),"auto");check("hammer repair enchantment accepts both durable relics",normal.is(net.minecraft.tags.TagKey.create(Registries.ITEM,ResourceLocation.parse("tc4modern:repairable")))&&broken.is(net.minecraft.tags.TagKey.create(Registries.ITEM,ResourceLocation.parse("tc4modern:repairable"))),"repairable");
 }
 public static void tick(ServerLevel l,int tick){if(sentry==null)return;targeted|=sentry.getTarget()==enemy;shot|=l.getEntitiesOfClass(Arrow.class,sentry.getBoundingBox().inflate(12)).stream().anyMatch(a->a.getOwner()==sentry);if(tick==190){check("native guardian AI selects hostile monster and shoots during real world ticks",targeted&&shot,targeted+"/"+shot);sentry.discard();enemy.discard();l.setChunkForced(forced.x,forced.z,false);sentry=null;}}
}
